// Centralize the run context (§3.4). Builds the condensed §6.3 agent panels
// (compact fields only — no OHLC arrays, no article bodies cross the LLM
// boundary, §2) and carries the prompts + deterministic rubric facts from
// POST /riskmanager/context. inputs_ok is false only when the context endpoint
// itself failed — a degraded *agent* still runs all three passes (§3.4 'runs
// three passes, always'); the prompts/clamp steer it toward avoid.
const trig = $('When Executed by Another Workflow').first().json;
const resp = $('Fetch Context').first().json;
const sentiment = trig.sentiment || {};
const earnings = trig.earnings || {};
const technical = trig.technical || {};
const prompts = resp.prompts || {};
const facts = resp.facts || {};

const inputsOk = Boolean(prompts.draft && prompts.critique && prompts.final && facts && facts.agreement_counts);
const degradeReason = inputsOk ? null : `riskmanager context unavailable (${resp.summary || (resp.error && resp.error.message) || 'no context'})`;

const sentimentPanel = {
  status: sentiment.status || 'ok',
  llm_sentiment: sentiment.llm_sentiment ?? null,
  model_sentiment: sentiment.model_sentiment ?? null,
  disagreement: sentiment.disagreement ?? null,
  summary: sentiment.summary || '',
};
const earningsPanel = {
  status: earnings.status || 'ok',
  is_window: (earnings.is_earnings_window ?? earnings.is_window) ?? false,
  materiality: earnings.materiality ?? null,
  summary: earnings.summary || '',
};
const technicalPanel = {
  status: technical.status || 'ok',
  signal: technical.signal ?? null,
  summary: technical.summary || '',
};
const agentStatus = {
  sentiment: sentiment.status || 'ok',
  earnings: earnings.status || 'ok',
  technical: technical.status || 'ok',
};

return [{ json: {
  ticker: trig.ticker,
  run_id: trig.run_id,
  sentiment: sentimentPanel,
  earnings: earningsPanel,
  technical: technicalPanel,
  agent_status: agentStatus,
  prompts,
  facts,
  inputs_ok: inputsOk,
  degrade_reason: degradeReason,
} }];

// Substitute the DRAFT template (§3.4 step 1) with the run context. Prompt
// carries only compact panels + rubric facts — never heavy data (§2).
const ctx = $('Prepare Context').first().json;
let t = ctx.prompts.draft;
t = t.split('{{TICKER}}').join(ctx.ticker);
t = t.split('{{SENTIMENT_JSON}}').join(JSON.stringify(ctx.sentiment));
t = t.split('{{EARNINGS_JSON}}').join(JSON.stringify(ctx.earnings));
t = t.split('{{TECHNICAL_JSON}}').join(JSON.stringify(ctx.technical));
t = t.split('{{RUBRIC_FACTS}}').join(JSON.stringify(ctx.facts));
return [{ json: { prompt: t } }];

// Parse the raw LLM text for POST /validate. A parse failure is NOT swallowed
// — it becomes an invalid payload so the validate -> retry -> degraded path
// handles it (§9.4).
const raw = ($json.text ?? '').toString().trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let payload;
try { payload = JSON.parse(raw); } catch (e) { payload = { _parse_error: String(e) }; }
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) { payload = { _not_an_object: true }; }
return [{ json: { agent: 'risk_draft', payload, raw } }];

// One automatic retry with a stricter instruction (§9.4). Validation errors
// from POST /validate are quoted back to the model.
const base = $('Build Draft Prompt').first().json.prompt;
const errors = $json.errors || [];
const prompt = base + '\n\nYour previous response was rejected by schema validation: ' + JSON.stringify(errors) + '\nRespond again with ONLY the JSON object described above — no prose, no markdown fences, no extra keys.';
return [{ json: { prompt } }];

const raw = ($json.text ?? '').toString().trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let payload;
try { payload = JSON.parse(raw); } catch (e) { payload = { _parse_error: String(e) }; }
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) { payload = { _not_an_object: true }; }
return [{ json: { agent: 'risk_draft', payload, raw } }];

// Normalize the committed draft from whichever parse produced the valid
// payload (direct or retry), so downstream passes reference one node.
let payload;
try { const p = $('Parse Draft (Retry)').first().json.payload; if (p && !p._parse_error && !p._not_an_object) payload = p; } catch (e) { /* retry never ran */ }
if (!payload) payload = $('Parse Draft').first().json.payload;
return [{ json: { draft: payload } }];

// Substitute the CRITIQUE template (§3.4 step 2): the draft is fed in to be
// attacked.
const ctx = $('Prepare Context').first().json;
const draft = $('Commit Draft').first().json.draft;
let t = ctx.prompts.critique;
t = t.split('{{TICKER}}').join(ctx.ticker);
t = t.split('{{SENTIMENT_JSON}}').join(JSON.stringify(ctx.sentiment));
t = t.split('{{EARNINGS_JSON}}').join(JSON.stringify(ctx.earnings));
t = t.split('{{TECHNICAL_JSON}}').join(JSON.stringify(ctx.technical));
t = t.split('{{DRAFT_JSON}}').join(JSON.stringify(draft));
t = t.split('{{RUBRIC_FACTS}}').join(JSON.stringify(ctx.facts));
return [{ json: { prompt: t } }];

const raw = ($json.text ?? '').toString().trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let payload;
try { payload = JSON.parse(raw); } catch (e) { payload = { _parse_error: String(e) }; }
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) { payload = { _not_an_object: true }; }
return [{ json: { agent: 'risk_critique', payload, raw } }];

const base = $('Build Critique Prompt').first().json.prompt;
const errors = $json.errors || [];
const prompt = base + '\n\nYour previous response was rejected by schema validation: ' + JSON.stringify(errors) + '\nRespond again with ONLY the JSON object described above — no prose, no markdown fences, no extra keys.';
return [{ json: { prompt } }];

const raw = ($json.text ?? '').toString().trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let payload;
try { payload = JSON.parse(raw); } catch (e) { payload = { _parse_error: String(e) }; }
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) { payload = { _not_an_object: true }; }
return [{ json: { agent: 'risk_critique', payload, raw } }];

let payload;
try { const p = $('Parse Critique (Retry)').first().json.payload; if (p && !p._parse_error && !p._not_an_object) payload = p; } catch (e) { /* retry never ran */ }
if (!payload) payload = $('Parse Critique').first().json.payload;
return [{ json: { critique: payload } }];

// Substitute the FINAL template (§3.4 step 3): draft + critique + rubric
// facts (which caps apply) are all fed in.
const ctx = $('Prepare Context').first().json;
const draft = $('Commit Draft').first().json.draft;
const critique = $('Commit Critique').first().json.critique;
let t = ctx.prompts.final;
t = t.split('{{TICKER}}').join(ctx.ticker);
t = t.split('{{SENTIMENT_JSON}}').join(JSON.stringify(ctx.sentiment));
t = t.split('{{EARNINGS_JSON}}').join(JSON.stringify(ctx.earnings));
t = t.split('{{TECHNICAL_JSON}}').join(JSON.stringify(ctx.technical));
t = t.split('{{DRAFT_JSON}}').join(JSON.stringify(draft));
t = t.split('{{CRITIQUE_JSON}}').join(JSON.stringify(critique));
t = t.split('{{RUBRIC_FACTS}}').join(JSON.stringify(ctx.facts));
return [{ json: { prompt: t } }];

const raw = ($json.text ?? '').toString().trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let payload;
try { payload = JSON.parse(raw); } catch (e) { payload = { _parse_error: String(e) }; }
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) { payload = { _not_an_object: true }; }
return [{ json: { agent: 'risk_final', payload, raw } }];

const base = $('Build Final Prompt').first().json.prompt;
const errors = $json.errors || [];
const prompt = base + '\n\nYour previous response was rejected by schema validation: ' + JSON.stringify(errors) + '\nRespond again with ONLY the JSON object described above — no prose, no markdown fences, no extra keys.';
return [{ json: { prompt } }];

const raw = ($json.text ?? '').toString().trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let payload;
try { payload = JSON.parse(raw); } catch (e) { payload = { _parse_error: String(e) }; }
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) { payload = { _not_an_object: true }; }
return [{ json: { agent: 'risk_final', payload, raw } }];

let payload;
try { const p = $('Parse Final (Retry)').first().json.payload; if (p && !p._parse_error && !p._not_an_object) payload = p; } catch (e) { /* retry never ran */ }
if (!payload) payload = $('Parse Final').first().json.payload;
return [{ json: { final: payload } }];

// Deterministic rubric clamp (§3.4) — the 'mechanism' half of the rubric.
// The LLM authored the final call; here it is enforced against the rubric so a
// violation (e.g. high conviction on 2-of-3 agreement) cannot reach the report.
// Every clamp is recorded and appended to the rationale — no silent rewrite.
const ctx = $('Prepare Context').first().json;
const facts = ctx.facts;
const draft = $('Commit Draft').first().json.draft;
const critique = $('Commit Critique').first().json.critique;
const final = { ...$('Commit Final').first().json.final };
const notes = [];
const order = { low: 0, medium: 1, high: 2 };

function capTo(level, why) {
  if (order[final.conviction] > order[level]) {
    notes.push(`conviction capped ${final.conviction} -> ${level}${why ? ` (${why})` : ''}`);
    final.conviction = level;
  }
}

// 1. Two or more degraded agents force avoid (§3.4) — insufficient evidence.
if (facts.caps && facts.caps.force_avoid) {
  if (final.recommendation !== 'avoid') {
    notes.push(`recommendation set to avoid (${facts.caps.degraded_count} degraded agents)`);
    final.recommendation = 'avoid';
  }
  final.conviction = 'low';
}

// 2. Agreement-count ceiling, resolved with the draft's LLM earnings_direction.
const earnDir = (draft && draft.earnings_direction) || 'neutral';
const counts = (facts.agreement_counts && facts.agreement_counts.by_earnings_direction[earnDir]) || { bullish: 0, bearish: 0 };
const side = final.recommendation === 'long' ? 'bullish' : (final.recommendation === 'short' ? 'bearish' : null);
if (side && !(facts.caps && facts.caps.force_avoid)) {
  const agree = counts[side];
  if (agree <= 1) {
    notes.push(`downgraded to hold (${agree} of 3 agents agree on ${side})`);
    final.recommendation = 'hold';
    final.conviction = 'low';
  } else if (agree === 2) {
    capTo('medium', '2 of 3 agreement');
  }
}

// 3. `short` requires at least one strong bearish signal (§3.4). The earnings
// part is direction-dependent, so it is resolved here with the draft's
// LLM-classified earnings_direction (facts.has_strong_bearish covers only the
// sentiment/technical part, known at context time).
const strongBearish = Boolean(facts.has_strong_bearish) || Boolean(facts.strong_signals && facts.strong_signals.earnings && earnDir === 'bearish');
if (final.recommendation === 'short' && !strongBearish) {
  notes.push('downgraded short -> hold (no strong bearish signal)');
  final.recommendation = 'hold';
  final.conviction = 'low';
}

// 3b. `avoid` is reserved for >=2 degraded agents (§3.4) — never a directional
// call. An avoid without force_avoid is a rubric violation; clamp it to hold.
if (final.recommendation === 'avoid' && !(facts.caps && facts.caps.force_avoid)) {
  notes.push('downgraded avoid -> hold (avoid reserved for >=2 degraded agents)');
  final.recommendation = 'hold';
  final.conviction = 'low';
}

// 4. Conviction caps: earnings-event, dual-sentiment, single degraded agent.
if (facts.caps && facts.caps.any_cap_medium && !facts.caps.force_avoid && (final.recommendation === 'long' || final.recommendation === 'short')) {
  const reasons = [];
  if (facts.caps.earnings_event) reasons.push('earnings event risk');
  if (facts.caps.dual_sentiment) reasons.push('dual-sentiment disagreement');
  if (facts.caps.degraded_count >= 1) reasons.push(`${facts.caps.degraded_count} degraded agent(s)`);
  capTo('medium', reasons.join(', '));
}

if (notes.length) {
  final.rationale = `${final.rationale}\n\n[Rubric clamp: ${notes.join('; ')}.]`;
}

return [{ json: {
  ticker: ctx.ticker,
  draft,
  critique,
  final,
  sentiment: ctx.sentiment,
  earnings: ctx.earnings,
  technical: ctx.technical,
  status: 'ok',
} }];

// Degraded result (§9.4): no fabrication. Reached when the context endpoint
// failed (Inputs OK? = false) or an LLM pass failed schema validation twice.
// Whatever passes completed are kept; missing passes are null; the final call
// is a safe hold.
const ctx = $('Prepare Context').first().json;
function tryGet(node, key) { try { return $(node).first().json[key]; } catch (e) { return null; } }
const draft = tryGet('Commit Draft', 'draft');
const critique = tryGet('Commit Critique', 'critique');

let reason;
if (ctx.inputs_ok === false) {
  reason = ctx.degrade_reason || 'risk manager context unavailable';
} else {
  let errs = [];
  for (const n of ['Validate Final (Retry)', 'Validate Critique (Retry)', 'Validate Draft (Retry)']) {
    try { const e = $(n).first().json.errors; if (e && e.length) { errs = e; break; } } catch (_) { /* pass never reached */ }
  }
  reason = 'an LLM pass failed schema validation after one stricter retry' + (errs.length ? ` (${errs.join('; ')})` : '');
}

return [{ json: {
  ticker: ctx.ticker,
  draft: draft || null,
  critique: critique || null,
  final: { recommendation: 'hold', conviction: 'low', rationale: `degraded: ${reason}` },
  sentiment: ctx.sentiment,
  earnings: ctx.earnings,
  technical: ctx.technical,
  status: 'degraded',
} }];
